package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Full original transports and adversarial family/precision/input mutations; no installed SMR dependency. */
class SmrWorkflowTest {
    @TempDir static Path corpus;@TempDir Path temporary;static List<String> protocols;
    static Map<String,Object> json(Path file)throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(Files.readAllBytes(file)),1048576,200000));}
    @BeforeAll static void load()throws Exception {
        try(var zip=new ZipInputStream(Objects.requireNonNull(SmrWorkflowTest.class.getResourceAsStream("/org/jlinalg/mr/smr/workflow-controls-v2.zip")))){for(var e=zip.getNextEntry();e!=null;e=zip.getNextEntry()){NextflowFiles.member(e.getName());byte[] raw=zip.readNBytes(32<<20);assertTrue(raw.length<(32<<20));Path target=corpus.resolve(e.getName());Files.createDirectories(target.getParent());Files.write(target,raw,StandardOpenOption.CREATE_NEW);}}
        var index=json(corpus.resolve("INDEX.json"));for(var e:object(index.get("files")).entrySet())assertEquals(NextflowFiles.fingerprint(e.getValue(),32<<20),NextflowFiles.pin(corpus.resolve(e.getKey()),32<<20,()->{}));protocols=strings(index.get("protocols"),1000);
    }
    static Stream<String> protocols(){return protocols.stream();}
    static SmrWorkflowRequest.Request request(Path root)throws IOException{return SmrWorkflowRequest.parse(json(root.resolve("request.json")),root);}
    record Loaded(SmrWorkflowRequest.Request request,SmrWorkflowInputs.Population population,SmrWorkflowInputs.Budget budget) { }
    static Loaded load(Path root)throws IOException {
        var r=request(root);var budget=new SmrWorkflowInputs.Budget(r.nativeOperations());Path inputs=root.resolve("inputs");var gwas=SmrWorkflowInputs.gwas(inputs.resolve("gwas.ma"),r,budget);var qtl=SmrWorkflowBesd.read(root.resolve("prepared/original"),r,budget);return new Loaded(r,SmrWorkflowInputs.population(inputs,qtl,gwas,r,budget),budget);
    }
    static void copy(Path from,Path to)throws IOException {Files.createDirectories(to);try(var paths=Files.walk(from)){for(Path path:paths.filter(Files::isRegularFile).toList()){Path target=to.resolve(from.relativize(path));Files.createDirectories(target.getParent());Files.copy(path,target);}}}
    Path original(String protocol)throws IOException {Path root=temporary.resolve("original");copy(corpus.resolve(protocol),root);return root;}
    @ParameterizedTest @MethodSource("protocols") void fullOriginalPopulationAndRatios(String protocol)throws Exception {
        Path root=original(protocol);var loaded=load(root);var r=loaded.request();if(r.qtl().get("kind").equals("qfile")){var supplied=SmrWorkflowInputs.qfile(root.resolve("inputs/qtl.qfile"),root.resolve("quantization.tsv"),r,loaded.budget());SmrWorkflowInputs.preparation(supplied,loaded.population().qtl(),root.resolve("prepared-audit.tsv"),loaded.budget());}int total=0;for(var a:r.analyses()){var warnings=new ArrayList<String>();Path home=root.resolve("cases").resolve(text(a.get("id")));var report=SmrWorkflowAudit.analysis(home,a,loaded.population(),r,loaded.budget(),warnings);assertTrue((Boolean)report.get("native_complete_family_and_ratio_checked"));assertFalse((Boolean)report.get("original_heidi_and_multi_tail_independently_refitted"));int rows=(int)report.get("original_rows");assertEquals(rows+1,Files.readAllLines(home.resolve("native-ratio-ledger.tsv")).size());total+=rows;}assertTrue(total>0);
    }
    static Stream<String> corruptions(){return Stream.of("missing-row","duplicate-row","extra-row","wrong-SNP","wrong-allele","wrong-beta","wrong-SE","wrong-P","zero-QTL-SE","nan-SMR","infinite-SMR","missing-HEIDI-off","wrong-probe-coordinate","swapped-probe-order");}
    @ParameterizedTest @MethodSource("corruptions") void rejectChangedOriginalRows(String mutation)throws Exception {
        Path root=original("1.3.1-sparse");var loaded=load(root);var cases=loaded.request().analyses();Map<String,Object> a=cases.stream().filter(c->c.get("id").equals(mutation.equals("missing-HEIDI-off")?"single-off":"single-new")).findFirst().orElseThrow();Path home=root.resolve("cases").resolve(text(a.get("id"))),table=home.resolve("original.smr");var rows=new ArrayList<>(Files.readAllLines(table));String[] row=rows.get(1).split("\t");
        switch(mutation){case "missing-row"->rows.remove(1);case "duplicate-row"->rows.add(rows.get(1));case "extra-row"->{row[0]="unknown-probe";rows.add(String.join("\t",row));}case "swapped-probe-order"->Collections.swap(rows,1,2);default->{switch(mutation){case "wrong-SNP"->row[4]="rsSynthetic2";case "wrong-allele"->row[7]="T";case "wrong-beta"->row[16]=".8";case "wrong-SE"->row[17]=".2";case "wrong-P"->row[18]=".9";case "zero-QTL-SE"->row[14]="0";case "nan-SMR"->row[16]="NaN";case "infinite-SMR"->row[17]="Inf";case "missing-HEIDI-off"->row[19]=".5";case "wrong-probe-coordinate"->row[3]="1";default->throw new AssertionError(mutation);}rows.set(1,String.join("\t",row));}}
        Files.write(table,rows,StandardCharsets.UTF_8);assertThrows(IOException.class,()->SmrWorkflowAudit.analysis(home,a,loaded.population(),loaded.request(),loaded.budget(),new ArrayList<>()));
    }
    @Test void truncatedAndTrailingBesdRefused()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);Path file=root.resolve("prepared/original.besd");byte[] raw=Files.readAllBytes(file);for(int delta:new int[]{-1,1}){Files.write(file,Arrays.copyOf(raw,raw.length+delta));assertThrows(IOException.class,()->SmrWorkflowBesd.read(root.resolve("prepared/original"),r,new SmrWorkflowInputs.Budget(r.nativeOperations())));}}
    @Test void duplicateGwasNeverRenamed()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);Path file=root.resolve("inputs/gwas.ma");var rows=Files.readAllLines(file);Files.writeString(file,Files.readString(file)+rows.get(1)+"\n");assertThrows(IOException.class,()->SmrWorkflowInputs.gwas(file,r,new SmrWorkflowInputs.Budget(r.nativeOperations())));}
    @Test void originalBothSeTermsAreRequired()throws Exception {Path root=original("1.3.1-sparse");var loaded=load(root);var a=loaded.request().analyses().get(0);Path home=root.resolve("cases").resolve(text(a.get("id"))),file=home.resolve("original.smr");var rows=Files.readAllLines(file);String[] row=rows.get(1).split("\t");row[17]=Double.toString(Double.parseDouble(row[11])/Double.parseDouble(row[13]));rows.set(1,String.join("\t",row));Files.write(file,rows);assertThrows(IOException.class,()->SmrWorkflowAudit.analysis(home,a,loaded.population(),loaded.request(),loaded.budget(),new ArrayList<>()));}
    @Test void losslessNumericOptionsArePassedAsLexemes()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);var options=SmrWorkflowCli.options(root.resolve("inputs"),root.resolve("prepared/original"),root.resolve("output"),r.analyses().get(0),r);assertEquals("5e-08",options.get(options.indexOf("--peqtl-smr")+1));assertFalse(options.stream().anyMatch(s->s.contains("NumberToken")));}
    @Test void inappropriateMultiOldHeidiIsRejected()throws Exception {Path root=original("1.3.1-sparse");var raw=json(root.resolve("request.json"));var a=object(list(raw.get("analyses")).get(1));a.put("kind","multi");a.put("multi",Map.of("window_kb",500,"ld_r2",.1));raw.put("analyses",List.of(a));assertThrows(IOException.class,()->SmrWorkflowRequest.parse(raw,root));}
    @Test void unappliedMafForHeidiOffRejected()throws Exception {Path root=original("1.3.1-sparse");var raw=json(root.resolve("request.json"));var a=object(list(raw.get("analyses")).get(2));a.put("minimum_maf",.01);raw.put("analyses",List.of(a));assertThrows(IOException.class,()->SmrWorkflowRequest.parse(raw,root));}
    @Test void unknownRequestOptionRejected()throws Exception {Path root=original("1.3.1-sparse");var raw=json(root.resolve("request.json"));raw.put("arbitrary_options",List.of("--foo"));assertThrows(IOException.class,()->SmrWorkflowRequest.parse(raw,root));}
    @Test void nativeBudgetCannotSilentlyReducePopulation()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);assertThrows(IOException.class,()->SmrWorkflowInputs.gwas(root.resolve("inputs/gwas.ma"),r,new SmrWorkflowInputs.Budget(1)));}
    @Test void sparseDuplicateSnpIndicesRefused()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);Path file=root.resolve("prepared/original.besd");byte[] raw=Files.readAllBytes(file);var buffer=java.nio.ByteBuffer.wrap(raw).order(java.nio.ByteOrder.LITTLE_ENDIAN);assertEquals(3,buffer.getInt(0));int np=buffer.getInt(12),rows=64+8+(2*np+1)*8;buffer.putInt(rows+4,buffer.getInt(rows));Files.write(file,raw);assertThrows(IOException.class,()->SmrWorkflowBesd.read(root.resolve("prepared/original"),r,new SmrWorkflowInputs.Budget(r.nativeOperations())));}
    @Test void sparseExplicitSentinelIsNotSilentlyDropped()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);Path file=root.resolve("prepared/original.besd");byte[] raw=Files.readAllBytes(file);var buffer=java.nio.ByteBuffer.wrap(raw).order(java.nio.ByteOrder.LITTLE_ENDIAN);int np=buffer.getInt(12);long values=buffer.getLong(64),se=buffer.getLong(80);int valueBase=Math.toIntExact(64+8+(2*np+1)*8+4*values);buffer.putFloat(valueBase,-9);buffer.putFloat(Math.toIntExact(valueBase+4*se),-9);Files.write(file,raw);assertThrows(IOException.class,()->SmrWorkflowBesd.read(root.resolve("prepared/original"),r,new SmrWorkflowInputs.Budget(r.nativeOperations())));}
    @Test void suppliedSeStillRequiresExactBinary32Identity()throws Exception {changedPreparationSeRejected("1.4.3-sparse",1);}
    @Test void legacyDerivedSeBeyondOneUlpIsRejected()throws Exception {changedPreparationSeRejected("1.3.1-sparse",2);}
    @Test void multiSnpCannotPretendToEstimateOverlap()throws Exception {Path root=original("1.3.1-sparse");var raw=json(root.resolve("request.json"));var a=object(list(raw.get("analyses")).get(3));a.put("sample_overlap",Map.of("kind","estimate-original","null_p",.01,"minimum_null_snps",2));raw.put("analyses",List.of(a));assertThrows(IOException.class,()->SmrWorkflowRequest.parse(raw,root));}
    @Test void singleSnpCannotUseUnestimatedMultiFlagMode()throws Exception {Path root=original("1.4.3-sparse");var raw=json(root.resolve("request.json"));var a=object(list(raw.get("analyses")).get(0));a.put("sample_overlap",Map.of("kind","source-flag-without-estimation"));raw.put("analyses",List.of(a));assertThrows(IOException.class,()->SmrWorkflowRequest.parse(raw,root));}
    @Test void undefinedXSexWeightsAreNotInventedOrComplemented()throws Exception {Path root=original("1.3.1-sparse");var r=request(root);Path file=root.resolve("inputs/reference.bim");var rows=Files.readAllLines(file);for(int i=0;i<rows.size();i++){String[] x=rows.get(i).split("\\s+");x[0]="23";rows.set(i,String.join("\t",x));}Files.write(file,rows);var budget=new SmrWorkflowInputs.Budget(r.nativeOperations());var gwas=SmrWorkflowInputs.gwas(root.resolve("inputs/gwas.ma"),r,budget);var qtl=SmrWorkflowBesd.read(root.resolve("prepared/original"),r,budget);var error=assertThrows(IOException.class,()->SmrWorkflowInputs.population(root.resolve("inputs"),qtl,gwas,r,budget));assertTrue(error.getMessage().contains("sex-weighted X frequency"));}
    void changedPreparationSeRejected(String protocol,int ulps)throws Exception {Path root=original(protocol);var r=request(root);var budget=new SmrWorkflowInputs.Budget(r.nativeOperations());var expected=SmrWorkflowInputs.qfile(root.resolve("inputs/qtl.qfile"),root.resolve("quantization.tsv"),r,budget);Path file=root.resolve("prepared/original.besd");byte[] raw=Files.readAllBytes(file);var buffer=java.nio.ByteBuffer.wrap(raw).order(java.nio.ByteOrder.LITTLE_ENDIAN);int np=buffer.getInt(12);long values=buffer.getLong(64),se=buffer.getLong(80);int offset=Math.toIntExact(64+8+(2*np+1)*8+4*values+4*se);buffer.putInt(offset,buffer.getInt(offset)+ulps);Files.write(file,raw);var changed=SmrWorkflowBesd.read(root.resolve("prepared/original"),r,budget);assertThrows(IOException.class,()->SmrWorkflowInputs.preparation(expected,changed,root.resolve("changed-prepare.tsv"),budget));}
}
